const firstNames = ["John", "Sarah", "Michael", "Emily", "David", "Jessica", "Robert", "Amanda", "Daniel", "Laura"];
const lastNames = ["Smith", "Johnson", "Williams", "Brown", "Davis", "Miller", "Wilson", "Moore", "Taylor", "Anderson"];
const statuses = ["active", "ACTIVE", "Inactive", "active", "pending", "Active"]; // intentionally inconsistent casing
const phoneFormats = [
  (n) => `(${n.slice(0,3)}) ${n.slice(3,6)}-${n.slice(6)}`,
  (n) => `${n.slice(0,3)}-${n.slice(3,6)}-${n.slice(6)}`,
  (n) => `+1${n}`,
  (n) => n // raw digits, no formatting
];

const dateFormats = [
  (d) => `${d.getMonth()+1}/${d.getDate()}/${d.getFullYear()}`,   // MM/DD/YYYY
  (d) => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`, // YYYY-MM-DD
  (d) => `${d.getDate()}-${d.getMonth()+1}-${d.getFullYear()}`,   // D-M-YYYY
];

const items = [];
for (let i = 0; i < 60; i++) {
  const first = firstNames[Math.floor(Math.random() * firstNames.length)];
  const last = lastNames[Math.floor(Math.random() * lastNames.length)];
  const fullName = Math.random() > 0.5 ? `${first} ${last}` : `${first.toUpperCase()} ${last.toUpperCase()}`;

  const rawPhone = String(Math.floor(2000000000 + Math.random() * 7999999999));
  const phoneFormatter = phoneFormats[Math.floor(Math.random() * phoneFormats.length)];

  const randomDate = new Date(2025, Math.floor(Math.random() * 12), Math.floor(1 + Math.random() * 28));
  const dateFormatter = dateFormats[Math.floor(Math.random() * dateFormats.length)];

  // 5% chance of missing email, simulating real-world nulls
  const hasEmail = Math.random() > 0.05;

  items.push({
    json: {
      customer_name: fullName,
      email: hasEmail ? `${first.toLowerCase()}.${last.toLowerCase()}@example.com` : null,
      phone: phoneFormatter(rawPhone),
      status: statuses[Math.floor(Math.random() * statuses.length)],
      created_at: dateFormatter(randomDate)
    }
  });
}

return items;

const invoices = [];

for (const item of items) {
  const accountId = item.json.id;
  const numInvoices = Math.floor(1 + Math.random() * 3);

  for (let i = 0; i < numInvoices; i++) {
    const rawAmount = (50 + Math.random() * 5000).toFixed(2);
    const amountFormats = [
      `$${Number(rawAmount).toLocaleString('en-US')}`,
      rawAmount,
      `USD ${rawAmount}`,
    ];
    const formattedAmount = amountFormats[Math.floor(Math.random() * amountFormats.length)];

    // Decide overdue-ness FIRST, then derive status and date consistently
    const scenario = Math.random();
    let daysOffset, invoiceStatus;

    if (scenario < 0.25) {
      // 25% paid — due date can be anywhere, doesn't matter
      daysOffset = Math.floor(-60 + Math.random() * 90);
      invoiceStatus = "paid";
    } else if (scenario < 0.45) {
      // 20% high risk — overdue 60+ days
      daysOffset = -Math.floor(61 + Math.random() * 60);
      invoiceStatus = "overdue";
    } else if (scenario < 0.65) {
      // 20% medium risk — overdue 31-60 days
      daysOffset = -Math.floor(31 + Math.random() * 30);
      invoiceStatus = "overdue";
    } else if (scenario < 0.80) {
      // 15% low risk — overdue 1-30 days
      daysOffset = -Math.floor(1 + Math.random() * 30);
      invoiceStatus = "overdue";
    } else {
      // 20% open, not yet due
      daysOffset = Math.floor(1 + Math.random() * 60);
      invoiceStatus = "open";
    }

    const dueDate = new Date();
    dueDate.setDate(dueDate.getDate() + daysOffset);

    invoices.push({
      json: {
        account_id: accountId,
        amount_due: formattedAmount,
        due_date: dueDate.toISOString().split('T')[0],
        invoice_status: invoiceStatus
      }
    });
  }
}

return invoices;

const channels = ["email", "phone", "sms", "letter"];
const outcomes = ["no answer", "left voicemail", "spoke with customer", "payment promised", "disputed", "wrong number"];

const contacts = [];

for (const item of items) {
  const accountId = item.json.account_id; // note: comes from invoices, but we log contact per account
  // We'll dedupe accounts later in SQL — for now, generate 0 to 3 contact attempts per invoice row
  const numContacts = Math.floor(Math.random() * 4); // 0 to 3

  for (let i = 0; i < numContacts; i++) {
    const daysAgo = Math.floor(Math.random() * 60);
    const contactDate = new Date();
    contactDate.setDate(contactDate.getDate() - daysAgo);

    contacts.push({
      json: {
        account_id: accountId,
        contact_date: contactDate.toISOString().split('T')[0],
        channel: channels[Math.floor(Math.random() * channels.length)],
        outcome: outcomes[Math.floor(Math.random() * outcomes.length)]
      }
    });
  }
}

return contacts;

const accountList = items.map(item =>
  `• *${item.json.customer_name}* — $${item.json.total_outstanding} outstanding, ${item.json.max_days_overdue} days overdue`
).join('\n');

const message = `⚠️ *High-Risk Accounts Alert*\n${items.length} account(s) flagged with 60+ days overdue:\n\n${accountList}`;

return [
  {
    json: {
      slack_message: message,
      account_count: items.length,
      accounts: items.map(item => ({
        customer_name: item.json.customer_name,
        total_outstanding: item.json.total_outstanding,
        max_days_overdue: item.json.max_days_overdue
      }))
    }
  }
];
